// The developer reference pages under /docs. The Rails backend keeps their
// markdown source (docs/*.md in calendar-backend) and serves it at
// /docs/<slug>.md, so an endpoint and its reference change in one pull request.
// This site renders that markdown at /docs/<slug>.
//
// /docs/api/openapi.json and /docs/api/schema.graphql are generated by the
// backend from its own code. They stay there: this site has no route for them,
// so the rproxy Worker falls back to Rails.
//
// This file imports nothing, so node --test and the layout can load it. The
// renderer is in server/renderDoc.ts, so marked stays out of the browser.

export type DeveloperDoc = {
	slug: string;
	title: string;
	description: string;
};

export const DOCS: DeveloperDoc[] = [
	{
		slug: 'api',
		title: 'Course Catalog API',
		description: 'Public read-only REST and GraphQL API for the Wentworth course catalog.'
	},
	{
		slug: 'mcp',
		title: 'MCP server reference',
		description: 'Connect Claude, ChatGPT, or another MCP client to your Wentworth schedule.'
	}
];

export function docFor(slug: string): DeveloperDoc | undefined {
	return DOCS.find((doc) => doc.slug === slug);
}

export function docPath(slug: string): string {
	return `/docs/${slug}`;
}

// The backend's copy of the markdown source.
export function sourcePath(slug: string): string {
	return `${docPath(slug)}.md`;
}
